import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9dce0');
scene.fog = new THREE.Fog('#b9e2dd', 32, 90);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 150);
const renderer = new THREE.WebGLRenderer({antialias:true, powerPreference:'high-performance'});
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.12;
document.body.prepend(renderer.domElement);

const hemi = new THREE.HemisphereLight('#e7fffb','#6a765f',2.1); scene.add(hemi);
const sun = new THREE.DirectionalLight('#fff0c4',3.2); sun.position.set(-12,23,10); sun.castShadow = true;
sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-24; sun.shadow.camera.right=24; sun.shadow.camera.top=30; sun.shadow.camera.bottom=-24; sun.shadow.bias=-.0005; scene.add(sun);
const moonLight = new THREE.DirectionalLight('#a9c5ff',0); moonLight.position.set(13,16,-14); scene.add(moonLight);

const blockGeo = new THREE.BoxGeometry(1,1,1);
function mat(color, rough=.92){return new THREE.MeshStandardMaterial({color,roughness:rough,flatShading:true})}
const mats={grass:mat('#79bd68'),dirt:mat('#a87954'),stone:mat('#777f7b'),deep:mat('#5f6b6d'),wood:mat('#98704d'),leaf:mat('#4b9e72'),sand:mat('#d6c48c'),flower:mat('#fff0a1'),crystal:mat('#77e6db',.35)};
const rand=(n)=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
function heightAt(x,z){return Math.round(1.0+Math.sin(x*.31)*1.0+Math.cos(z*.27)*.8+Math.sin((x+z)*.22)*.65)}
function edgeAt(x,z){return 14.2 + (rand((x+24)*27+z+41)-.5)*1.1 + Math.sin(x*.7+z*.31)*.4}
const batches={grass:[],dirt:[],stone:[],deep:[]}; const topBlocks=new Map();
for(let x=-15;x<=15;x++)for(let z=-15;z<=15;z++){
  const dist=Math.sqrt(x*x*1.03+z*z*.94); if(dist>edgeAt(x,z))continue;
  const h=heightAt(x,z); topBlocks.set(`${x},${z}`,{x,y:h,z,type:'grass',removed:false});
  batches.grass.push({x,y:h,z});
  const underRadius=14.2 - Math.max(0, -h)*.12;
  const depth=Math.max(1, Math.floor(8 - dist*.18 + rand(x*12+z)*2));
  for(let d=1;d<=depth;d++){
    const yy=h-d; let type=d<=2?'dirt':(d>depth-2?'deep':'stone');
    if(d>2 && dist>underRadius && d>4)continue;
    batches[type].push({x,y:yy,z});
  }
}
const terrainMeshes=[]; const terrainHitMeshes=[];
for(const type of Object.keys(batches)){
 const items=batches[type], mesh=new THREE.InstancedMesh(blockGeo,mats[type],items.length); mesh.castShadow=true; mesh.receiveShadow=true;
 const dummy=new THREE.Object3D(); items.forEach((b,i)=>{dummy.position.set(b.x,b.y,b.z);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);
   const v= .88+rand(b.x*155+b.z*73+b.y*11)*.22; mesh.setColorAt(i,new THREE.Color(v,v,v)); });
 mesh.instanceMatrix.needsUpdate=true; if(mesh.instanceColor)mesh.instanceColor.needsUpdate=true;
 scene.add(mesh); terrainMeshes.push(mesh); terrainHitMeshes.push(mesh);
}

// Decorative block clusters use their own lightweight cubes.
const decoGroup=new THREE.Group(); scene.add(decoGroup);
function cube(x,y,z,sx,sy,sz,material, parent=decoGroup){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function groundY(x,z){return heightAt(Math.round(x),Math.round(z))+.55}
function tree(x,z,scale=1){const y=groundY(x,z);for(let i=0;i<4*scale;i++)cube(x,y+i+.5,z,.72*scale,.9,.72*scale,mats.wood);
 for(let layer=0;layer<3;layer++){let r=2-layer*.35;for(let dx=-2;dx<=2;dx++)for(let dz=-2;dz<=2;dz++)if(Math.abs(dx)+Math.abs(dz)<4 && rand(x*30+z*13+dx*4+dz+layer*7)>.14)cube(x+dx*.72*scale,y+3.3+layer*.75,z+dz*.72*scale,.85*scale,.85*scale,.85*scale,mats.leaf);}
 cube(x,y+5.25,z,.75*scale,.8,.75*scale,mats.leaf);
}
tree(-7,-3,1);tree(7,-7,.88);tree(9,4,.9);tree(-10,6,.82);tree(1,10,.78);
// A welcoming little cabin at the far edge.
const cabinX=-5,cabinZ=7, cabinY=groundY(cabinX,cabinZ);
for(let x=0;x<5;x++)for(let z=0;z<4;z++)cube(cabinX+x,cabinY,cabinZ+z,1,.28,1,mats.wood);
for(let y=1;y<=3;y++)for(let x=0;x<5;x++)for(let z of [0,3])cube(cabinX+x,cabinY+y,cabinZ+z,1,1,1,(y===3?mats.wood:(x===2&&y<3?mats.dirt:mats.wood)));
for(let y=1;y<=3;y++)for(let z=1;z<=2;z++)for(let x of [0,4])cube(cabinX+x,cabinY+y,cabinZ+z,1,1,1,mats.wood);
for(let x=-1;x<=5;x++)for(let z=-1;z<=4;z++){let roof=cube(cabinX+x,cabinY+4-Math.min(Math.abs(x-2),Math.abs(z-1.5)*.25),cabinZ+z,1,.6,1,mats.dirt);}
// Soft paths and flower patches.
for(let i=0;i<20;i++){let x=-1+i*.36,z=2+Math.sin(i*.22)*.6;let b=topBlocks.get(`${Math.round(x)},${Math.round(z)}`);if(b)cube(x,b.y+.52,z,.65,.1,.65,mats.sand);}
for(let i=0;i<52;i++){let a=rand(i*2+8)*Math.PI*2,r=4+rand(i*3+5)*8,x=Math.round(Math.cos(a)*r),z=Math.round(Math.sin(a)*r);const b=topBlocks.get(`${x},${z}`);if(b&&rand(i+77)>.45){cube(x,b.y+.9,z,.22,.38,.22,mats.leaf);cube(x,b.y+1.12,z,.28,.18,.28,mats.flower);}}

