const clouds=new THREE.Group();scene.add(clouds);
for(let i=0;i<22;i++){let a=rand(i*21+4)*Math.PI*2,r=20+rand(i*3)*16,x=Math.cos(a)*r,z=Math.sin(a)*r,y=-4+rand(i*13)*6;
 const c=new THREE.Mesh(new THREE.SphereGeometry(1,8,6),new THREE.MeshStandardMaterial({color:'#f5fbf4',roughness:1,transparent:true,opacity:.7})); c.scale.set(2.6+rand(i)*2, .75+rand(i+33)*.7,1.8+rand(i+5)*2);c.position.set(x,y,z);clouds.add(c);}
// Floating crystals, the island's tiny scavenger hunt.
const crystalSpots=[[-9,1], [4,-10], [10,1]]; const crystalMeshes=[];
const crystalGeo=new THREE.OctahedronGeometry(.55,0);
crystalSpots.forEach(([x,z],i)=>{const b=topBlocks.get(`${x},${z}`);if(!b)return;
 const group=new THREE.Group();group.position.set(x,b.y+1.35,z);group.userData={id:i,base:b.y+1.35};
 const c=new THREE.Mesh(crystalGeo,new THREE.MeshStandardMaterial({color:'#85fff1',emissive:'#24b8a9',emissiveIntensity:1.2,roughness:.18,metalness:.12}));c.scale.set(.7,1.25,.7);c.castShadow=true;group.add(c);
 const glow=new THREE.PointLight('#67fff0',1.8,5);glow.position.y=.2;group.add(glow);scene.add(group);crystalMeshes.push(group);
});
// Player camera and tiny block-person avatar.
const player={x:0,z:0,y:0,vy:0,grounded:true,yaw:Math.PI*.78,pitch:-.12};
const avatar=new THREE.Group();scene.add(avatar);
const skin=mat('#e4aa80'),shirt=mat('#d98368'),pants=mat('#52697a'),hair=mat('#674b3c');
cube(0,.15,0,.62,.3,.44,mats.wood,avatar);
cube(0,.68,0,.56,.78,.42,shirt,avatar);cube(0,1.35,0,.54,.52,.5,skin,avatar);cube(0,1.65,-.04,.58,.2,.54,hair,avatar);
cube(-.13,1.39,.258,.055,.055,.025,mat('#3c4647'),avatar);cube(.13,1.39,.258,.055,.055,.025,mat('#3c4647'),avatar);
cube(-.17,-.05,0,.2,.45,.25,pants,avatar);cube(.17,-.05,0,.2,.45,.25,pants,avatar);
avatar.visible=false;
const raycaster=new THREE.Raycaster();raycaster.far=5.5;
function updateCamera(){const eye=new THREE.Vector3(player.x,player.y+1.3,player.z);const dir=new THREE.Vector3(Math.sin(player.yaw)*Math.cos(player.pitch),Math.sin(player.pitch),Math.cos(player.yaw)*Math.cos(player.pitch));camera.position.copy(eye).addScaledVector(dir,-4.8);camera.position.y+=1.3;camera.lookAt(eye.x+dir.x*3,eye.y+dir.y*3,eye.z+dir.z*3);avatar.position.set(player.x,player.y,player.z);avatar.rotation.y=player.yaw+Math.PI;}
updateCamera();

