updateCamera();

// A responsive, simple block interaction layer. Break and replace the top voxel at the crosshair.
const edits=new Map();let selected=0, crystalsFound=0, toastTimer=0;
const toast=document.getElementById('toast'), crosshair=document.getElementById('crosshair');
function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),900);}
function pick(){raycaster.setFromCamera(new THREE.Vector2(0,0),camera);const hit=raycaster.intersectObjects(terrainHitMeshes,false)[0];return hit||null;}
function interact(action){const hit=pick();if(!hit){showToast('Nothing in reach');return;}
 const mesh=hit.object, index=hit.instanceId, inverse=new THREE.Matrix4().copy(mesh.matrixWorld).invert();const local=hit.point.clone().applyMatrix4(inverse);const normal=hit.face.normal.clone();
 const cell=new THREE.Vector3(Math.floor(local.x-normal.x*.02+.5),Math.floor(local.y-normal.y*.02+.5),Math.floor(local.z-normal.z*.02+.5));
 const key=`${Math.round(cell.x)},${Math.round(cell.y)},${Math.round(cell.z)}`;
 if(action==='break'){
   if(player.x-cell.x<-.8 && false)return;
   const dummy=new THREE.Object3D();dummy.position.set(0,-100,0);dummy.updateMatrix();mesh.setMatrixAt(index,dummy.matrix);mesh.instanceMatrix.needsUpdate=true;
